#!/usr/bin/env node
/**
 * check-deploy-bundle.mjs
 *
 * The installer carries the two BYO deploy runtimes (`cloud/` and `cloud-aws/`,
 * plus the `engine/` they both resolve `@phorma/engine` through) as Tauri
 * resources, so a production install can deploy without a checkout of this
 * repository. `bundle.resources` in `backend/src-tauri/tauri.conf.json` is the
 * manifest, and it is a hand-written list of paths.
 *
 * That makes two silent failure modes possible, both of which only surface as a
 * broken deploy on a user's machine long after the release:
 *
 * 1. A listed path is renamed or deleted, so the resource never ships.
 * 2. A NEW top-level file or folder the runtime needs is added to a package and
 *    nobody remembers to list it.
 *
 * This guard closes both. Every listed source path must exist, and every
 * top-level entry of the three packages must be either bundled or named in
 * NOT_BUNDLED below with a reason - so adding one forces a decision instead of
 * an omission. Nested files inside a bundled folder need no entry.
 *
 * Run: node scripts/check-deploy-bundle.mjs
 */
import { existsSync, readdirSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const CONF = resolve(ROOT, 'backend', 'src-tauri', 'tauri.conf.json');

/**
 * Top-level entries deliberately left out of the installer, and why. A deploy
 * runs `npm install` and then one CLI verb; it never type-checks and never runs a
 * test, so the test and tooling trees stay out and keep the installer small.
 */
const NOT_BUNDLED = {
  'cloud/.dev.vars.example':
    'template for a LOCAL `wrangler dev`; the materialized workspace only deploys, and its secrets are set through the studio (`wrangler secret put`)',
  'cloud/.gitignore': 'git metadata has no meaning in a materialized workspace',
  'cloud/.wrangler/': 'wrangler scratch state, recreated locally',
  'cloud/dist/': 'build output of `npm run check`',
  // `wrangler deploy --env hosted --outdir=dist-hosted` leaves this behind, so it
  // appears on any machine that has deployed the hosted worker (the release
  // playbook's Phase 7). Gitignored by `cloud/dist*/` like `dist/`, and listed in
  // GENERATED below for the same reason: a fresh CI checkout does not have it.
  'cloud/dist-hosted/': 'build output of a hosted `wrangler deploy --outdir`',
  'cloud/test/': 'test suite, not part of `wrangler deploy`',
  'cloud-aws/cdk.context.json': 'CDK lookup cache, regenerated per account',
  'cloud-aws/cdk.out/': 'synth output, regenerated by every plan',
  'cloud-aws/dist/':
    'Schedule_Shim Lambda bundle - build output, rebuilt in the workspace by the plan and deploy verbs (src/cli/shim-bundle.ts) so it can never be stale',
  'cloud/scripts/':
    'operator migration scripts (the OpenRouter workspace re-provision). They run against the HOSTED database with the management key and are never part of a deploy - shipping them would put a production runbook in every BYO installer',
  'cloud-aws/scripts/': 'check-pipeline guards, not part of a deploy',
  'cloud-aws/test/': 'test suite and fixtures',
  'cloud-aws/vitest.config.ts': 'test runner configuration',
  'engine/package-lock.json': 'engine is consumed as `file:../engine` source, never installed alone',
  'engine/test/': 'scenario scripts',
  'engine/tsconfig.json': 'each host resolves engine source through its OWN tsconfig paths',
  'engine/vitest.config.ts': 'test runner configuration',
};

/**
 * NOT_BUNDLED entries that exist only after a local build or CLI run. The
 * liveness check at the bottom must skip them: a fresh checkout has none of
 * them, so requiring them to exist fails every CI run while passing on any
 * machine that happens to have built. A stale entry here is pruned when the
 * tool that writes the path goes away, which is a code change, not a state one.
 */
const GENERATED = new Set([
  'cloud/.wrangler/',
  'cloud/dist/',
  'cloud/dist-hosted/',
  'cloud-aws/cdk.context.json',
  'cloud-aws/cdk.out/',
  'cloud-aws/dist/',
]);

/**
 * Per-developer local artefacts: gitignored, machine-specific, never shipped.
 * They cannot be NOT_BUNDLED entries because the liveness check at the bottom
 * requires every entry to exist - the same problem GENERATED solves, one level
 * less predictable, since these appear only on a machine that ran the thing
 * that writes them. Without this skip, writing a `.dev.vars` to work on hosted
 * mode locally, or configuring a BYO override in Settings > Cloud, fails the
 * guard on your machine and nowhere else.
 *
 * Matched on the entry NAME, and checked AFTER NOT_BUNDLED so a tracked file
 * with a matching name (`.dev.vars.example`) still has to earn its line above.
 */
const LOCAL_ONLY = [
  /^\.dev\.vars(\..+)?$/, // wrangler local secrets, including `.dev.vars.<env>`
  /^\.env(\..+)?$/, // ditto, dotenv form
  /^wrangler\.byo\.jsonc$/, // per-user override written by Settings > Cloud
  // `--out` from `scripts/migrate-openrouter-workspace.mjs`, which an operator is
  // told to write while planning a migration. It is also the one artefact here
  // that carries LIVE tenant ids and OpenRouter key hashes, so `cloud/.gitignore`
  // covers the same names - this skip only stops the guard failing on a machine
  // that ran the documented procedure.
  /^report\.json$/,
  /-report\.json$/,
];

/** Packages whose top-level entries must be accounted for. */
const PACKAGES = ['cloud', 'cloud-aws', 'engine'];

const failures = [];

const resources = JSON.parse(readFileSync(CONF, 'utf-8')).bundle?.resources;
if (!resources || Array.isArray(resources) || typeof resources !== 'object') {
  console.error(
    'bundle.resources must be an OBJECT map in tauri.conf.json. The array form ' +
      'mangles paths outside src-tauri into `_up_/_up_/...` directories.',
  );
  process.exit(1);
}

// Source paths in the map are relative to backend/src-tauri.
const sources = Object.keys(resources).map((source) => ({
  source,
  absolute: resolve(ROOT, 'backend', 'src-tauri', source),
}));

for (const { source, absolute } of sources) {
  if (!existsSync(absolute)) {
    failures.push(`bundle.resources lists "${source}", which does not exist`);
  }
}

/** Whether `entry` (for example `cloud/src/`) is covered by the manifest. */
function isBundled(entry) {
  const needle = `/${entry}`.replace(/\/$/, '');
  return sources.some(({ source }) => {
    const listed = source.replace(/^\.\.\/\.\./, '').replace(/\/$/, '');
    return listed === needle;
  });
}

for (const pkg of PACKAGES) {
  for (const dirent of readdirSync(resolve(ROOT, pkg), { withFileTypes: true })) {
    if (dirent.name === 'node_modules') continue;
    const entry = `${pkg}/${dirent.name}${dirent.isDirectory() ? '/' : ''}`;
    if (isBundled(entry)) {
      if (entry in NOT_BUNDLED) {
        failures.push(`"${entry}" is both bundled and listed in NOT_BUNDLED - pick one`);
      }
      continue;
    }
    if (entry in NOT_BUNDLED) continue;
    if (LOCAL_ONLY.some((pattern) => pattern.test(dirent.name))) continue;
    failures.push(
      `"${entry}" is neither bundled nor in NOT_BUNDLED. Add it to ` +
        'bundle.resources if a deploy needs it, or to NOT_BUNDLED with a reason.',
    );
  }
}

for (const entry of GENERATED) {
  if (!(entry in NOT_BUNDLED)) {
    failures.push(`GENERATED names "${entry}", which is not in NOT_BUNDLED - one of the two is stale`);
  }
}

for (const entry of Object.keys(NOT_BUNDLED)) {
  if (GENERATED.has(entry)) continue;
  const path = resolve(ROOT, entry);
  if (!existsSync(path)) {
    failures.push(`NOT_BUNDLED names "${entry}", which no longer exists - prune it`);
  }
}

if (failures.length > 0) {
  for (const failure of failures) console.error(`  FAIL: ${failure}`);
  console.error(`\ncheck-deploy-bundle FAILED with ${failures.length} failure(s).`);
  process.exit(1);
}

console.log(`check-deploy-bundle passed: ${sources.length} resource paths verified.`);
